package com.studenttracker.service;
import com.studenttracker.database.DatabaseManager; import java.sql.*; import java.util.*;
public class ProductivityService {private final DatabaseManager db; public ProductivityService(DatabaseManager db){this.db=db;} public Map<String,Integer> subjectMinutes(){Map<String,Integer> m=new HashMap<>();try(Statement s=db.getConnection().createStatement();ResultSet r=s.executeQuery("SELECT subject,SUM(minutes) total FROM study_sessions GROUP BY subject ORDER BY total DESC")){while(r.next())m.put(r.getString(1),r.getInt(2));}catch(SQLException e){throw new RuntimeException(e);}return m;} public int count(String status){try(PreparedStatement p=db.getConnection().prepareStatement("SELECT COUNT(*) FROM tasks WHERE status=?")){p.setString(1,status);try(ResultSet r=p.executeQuery()){return r.next()?r.getInt(1):0;}}catch(SQLException e){throw new RuntimeException(e);}} public int overdue(){try(PreparedStatement p=db.getConnection().prepareStatement("SELECT COUNT(*) FROM tasks WHERE status <> 'COMPLETED' AND deadline < date('now')");ResultSet r=p.executeQuery()){return r.next()?r.getInt(1):0;}catch(SQLException e){throw new RuntimeException(e);}} }
